#include <agent/toolbus/tool_effect_journal.hpp>
namespace agent_framework { bool ToolEffectJournal::start(ToolEffectRecord r){if(r.idempotency_key.empty())return false;std::lock_guard<std::mutex>l(m_);if(by_key_.contains(r.idempotency_key))return false;r.status=ToolEffectStatus::Started;by_key_.emplace(r.idempotency_key,std::move(r));return true;} bool ToolEffectJournal::complete(const std::string&k,const std::string&d){std::lock_guard<std::mutex>l(m_);auto i=by_key_.find(k);if(i==by_key_.end()||i->second.status!=ToolEffectStatus::Started)return false;i->second.status=ToolEffectStatus::Completed;i->second.result_digest=d;return true;} bool ToolEffectJournal::commit(const std::string&k){std::lock_guard<std::mutex>l(m_);auto i=by_key_.find(k);if(i==by_key_.end()||i->second.status!=ToolEffectStatus::Completed)return false;i->second.status=ToolEffectStatus::Committed;return true;} std::optional<ToolEffectRecord> ToolEffectJournal::find_idempotency(const std::string&k)const{std::lock_guard<std::mutex>l(m_);auto i=by_key_.find(k);return i==by_key_.end()?std::nullopt:std::optional<ToolEffectRecord>(i->second);} std::vector<ToolEffectRecord> ToolEffectJournal::recoverable()const{std::lock_guard<std::mutex>l(m_);std::vector<ToolEffectRecord>r;for(const auto&[_,x]:by_key_)if(x.status==ToolEffectStatus::Started||x.status==ToolEffectStatus::Completed)r.push_back(x);return r;} }
